                if (feature.equals("extendedElement")) {
                    return new HashSet<Object>(Model.getFacade()
                            .getExtendedElements(subject));
                }
                if (feature.equals("definedTag")) {
                    return new HashSet<Object>(Model.getFacade()
                            .getTagDefinitions(subject));
                }
                // stereotypeConstraint ?
            }
        }

